// Turns new customer DMs into conversation turns. Seen message ids live in the workflow's
// static data; the first run only records what is already there, so old DMs are not answered.
const own = $('Get Instagram account').first().json.instagram_business_account?.id;
const conversations = $input.first().json.data || [];
const store = $getWorkflowStaticData('global');
const firstRun = !store.seen;
store.seen = store.seen || {};
const cutoff = Date.now() - 15 * 60 * 1000;
const out = [];
for (const conversation of conversations) {
  const messages = [...(conversation.messages?.data || [])].reverse();   // oldest first
  for (const m of messages) {
    if (store.seen[m.id]) continue;
    store.seen[m.id] = Date.now();
    if (firstRun || !own) continue;
    if (!m.message || !m.from?.id || m.from.id === own) continue;      // our own replies
    if (new Date(m.created_time).getTime() < cutoff) continue;
    out.push({ json: { provider: 'INSTAGRAM', externalUserId: m.from.id, recipientId: m.from.id, displayName: m.from.username || null, text: m.message, mid: m.id } });
  }
}
const ids = Object.keys(store.seen);
if (ids.length > 1000) ids.sort((a, b) => store.seen[a] - store.seen[b]).slice(0, ids.length - 500).forEach(id => delete store.seen[id]);
return out;
